def summarize_orders(orders, currency="USD", min_total=0.0):
    """Summarize a list of order dicts into totals per customer.

    Each order has keys: id, customer, items (list of {sku, qty, price}), status.
    Cancelled orders are skipped. Totals below min_total are dropped.
    """
    totals = {}
    counts = {}
    for order in orders:
        if order.get("status") == "cancelled":
            continue
        customer = order["customer"]
        subtotal = 0.0
        for item in order["items"]:
            qty = item.get("qty", 1)
            price = item.get("price", 0.0)
            subtotal += qty * price
        totals[customer] = totals.get(customer, 0.0) + subtotal
        counts[customer] = counts.get(customer, 0) + 1
    result = []
    for customer, total in sorted(totals.items()):
        if total < min_total:
            continue
        result.append({
            "customer": customer,
            "orders": counts[customer],
            "total": round(total, 2),
            "currency": currency,
        })
    return result
